sys_script.script:
(function executeRule(current, previous) {

    // BR-MED-05
    // Keep Medication Status and Active flag consistent.

    var status = current.getValue('medication_status');

    // Active medication must have Active = true.
    if (status == 'Active' && current.active != true) {

        gs.addErrorMessage(
            'Medication with Active status must have Active set to true.'
        );

        current.setAbortAction(true);
        return;
    }

    // Completed medication must be inactive.
    if (status == 'Completed' && current.active == true) {

        gs.addErrorMessage(
            'Completed Medication must have Active set to false.'
        );

        current.setAbortAction(true);
        return;
    }

    // Discontinued medication must be inactive.
    if (status == 'Discontinued' && current.active == true) {

        gs.addErrorMessage(
            'Discontinued Medication must have Active set to false.'
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
